"use client";

import React, {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useSyncExternalStore,
} from "react";
import { DEFAULT_LOCALE, type Locale } from "./config";
import type { AppDictionaries, Namespace, TranslateFn } from "./types";
import { formatMessage } from "./format";
import { useLocaleStore } from "@/shared/hooks/useLocaleStore";

// Static imports to pre-seed dictionary cache (eliminates flash of unloaded text on page reload)
import bnCommon from "./dictionaries/bn/common.json";
import bnHome from "./dictionaries/bn/home.json";
import bnAbout from "./dictionaries/bn/about.json";
import bnPrograms from "./dictionaries/bn/programs.json";
import bnVolunteer from "./dictionaries/bn/volunteer.json";
import bnReport from "./dictionaries/bn/report.json";
import bnHelpCenter from "./dictionaries/bn/helpCenter.json";
import enCommon from "./dictionaries/en/common.json";
import enHome from "./dictionaries/en/home.json";
import enAbout from "./dictionaries/en/about.json";
import enPrograms from "./dictionaries/en/programs.json";
import enVolunteer from "./dictionaries/en/volunteer.json";
import enReport from "./dictionaries/en/report.json";
import enHelpCenter from "./dictionaries/en/helpCenter.json";

const dictionaryCache = new Map<string, AppDictionaries[Namespace]>([
  ["bn:common", bnCommon as AppDictionaries["common"]],
  ["bn:home", bnHome as AppDictionaries["home"]],
  ["bn:about", bnAbout as AppDictionaries["about"]],
  ["bn:programs", bnPrograms as AppDictionaries["programs"]],
  ["bn:volunteer", bnVolunteer as AppDictionaries["volunteer"]],
  ["bn:report", bnReport as AppDictionaries["report"]],
  ["bn:helpCenter", bnHelpCenter as AppDictionaries["helpCenter"]],
  ["en:common", enCommon as AppDictionaries["common"]],
  ["en:home", enHome as AppDictionaries["home"]],
  ["en:about", enAbout as AppDictionaries["about"]],
  ["en:programs", enPrograms as AppDictionaries["programs"]],
  ["en:volunteer", enVolunteer as AppDictionaries["volunteer"]],
  ["en:report", enReport as AppDictionaries["report"]],
  ["en:helpCenter", enHelpCenter as AppDictionaries["helpCenter"]],
]);

const inFlightRequests = new Map<string, Promise<AppDictionaries[Namespace]>>();
const listeners = new Set<() => void>();

function notify() {
  listeners.forEach((listener) => listener());
}

function subscribe(listener: () => void) {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Dynamically loads a namespace dictionary for the given locale.
 * Caches loaded dictionaries in-memory so subsequent requests are instant.
 */
export async function loadNamespace<N extends Namespace>(
  locale: Locale,
  namespace: N
): Promise<AppDictionaries[N]> {
  const cacheKey = `${locale}:${namespace}`;
  const cached = dictionaryCache.get(cacheKey);
  if (cached) return cached as AppDictionaries[N];

  const inFlight = inFlightRequests.get(cacheKey);
  if (inFlight) return inFlight as Promise<AppDictionaries[N]>;

  const promise = (async () => {
    try {
      const mod = await import(`./dictionaries/${locale}/${namespace}.json`);
      const dict = (mod.default ?? mod) as AppDictionaries[N];
      dictionaryCache.set(cacheKey, dict);
      notify();
      return dict;
    } finally {
      inFlightRequests.delete(cacheKey);
    }
  })();

  inFlightRequests.set(cacheKey, promise);
  return promise;
}

interface I18nContextValue {
  locale: Locale;
}

const I18nContext = createContext<I18nContextValue>({
  locale: DEFAULT_LOCALE,
});

interface I18nProviderProps {
  children: React.ReactNode;
  initialLocale?: Locale;
}

/**
 * I18nProvider — wraps the app (inside Providers) to supply translations
 * to all Client Components. Synchronizes with useLocaleStore.
 */
export function I18nProvider({ children, initialLocale }: I18nProviderProps) {
  const storeLocale = useLocaleStore((s) => s.locale);
  const activeLocale = initialLocale || storeLocale || DEFAULT_LOCALE;

  const value = useMemo<I18nContextValue>(() => {
    return {
      locale: activeLocale,
    };
  }, [activeLocale]);

  return <I18nContext.Provider value={value}>{children}</I18nContext.Provider>;
}

/**
 * Client-side translation hook with strict TypeScript autocompletion and reactive updates.
 * Automatically loads requested namespace on demand and re-renders when loaded.
 *
 * Usage:
 *   const t = useTranslations("common");
 *   <button>{t("buttons.donateNow")}</button>
 */
export function useTranslations<N extends Namespace>(namespace: N): TranslateFn<N> {
  const locale = useCurrentLocale();
  const cacheKey = `${locale}:${namespace}`;

  useEffect(() => {
    if (!dictionaryCache.has(cacheKey)) {
      void loadNamespace(locale, namespace);
    }
  }, [cacheKey, locale, namespace]);

  const dict = useSyncExternalStore(
    subscribe,
    () => dictionaryCache.get(cacheKey) as AppDictionaries[N] | undefined,
    () => dictionaryCache.get(cacheKey) as AppDictionaries[N] | undefined
  );

  return useMemo(() => {
    return ((key, params) => {
      if (!dict) return key;
      return formatMessage(dict as Record<string, unknown>, key, params);
    }) as TranslateFn<N>;
  }, [dict]);
}

/**
 * Hook to access the current client locale
 */
export function useCurrentLocale(): Locale {
  const { locale } = useContext(I18nContext);
  return locale;
}
