import { create } from "zustand";
import { persist, createJSONStorage } from "zustand/middleware";
import {
  DEFAULT_LOCALE,
  LOCALE_COOKIE_NAME,
  LOCALE_CONFIGS,
  ALL_LOCALE_HTML_CLASSES,
  type Locale,
} from "@/shared/i18n/config";

interface LocaleStore {
  locale: Locale;
  setLocale: (locale: Locale) => void;
  toggleLocale: () => void;
}

function syncDomWithLocale(locale: Locale) {
  if (typeof document === "undefined") return;

  const html = document.documentElement;
  const config = LOCALE_CONFIGS[locale];

  // 1. Sync HTML lang attribute
  html.setAttribute("lang", config.code);

  // 2. Sync HTML font class
  html.classList.remove(...ALL_LOCALE_HTML_CLASSES);
  html.classList.add(config.htmlClass);

  // 3. Sync cookie for Server Component rendering (1 year expiration)
  document.cookie = `${LOCALE_COOKIE_NAME}=${locale}; path=/; max-age=31536000; SameSite=Lax`;
}

export const useLocaleStore = create<LocaleStore>()(
  persist(
    (set, get) => ({
      locale: DEFAULT_LOCALE,
      setLocale: (locale: Locale) => {
        syncDomWithLocale(locale);
        set({ locale });
      },
      toggleLocale: () => {
        const current = get().locale;
        const next: Locale = current === "bn" ? "en" : "bn";
        syncDomWithLocale(next);
        set({ locale: next });
      },
    }),
    {
      name: "shelter-locale-preference",
      storage: createJSONStorage(() => localStorage),
      skipHydration: true,
      onRehydrateStorage: () => (state) => {
        if (state) {
          syncDomWithLocale(state.locale);
        }
      },
    }
  )
);
