"use client";

import { useLocaleStore } from "@/shared/hooks/useLocaleStore";
import { LOCALES, type Locale } from "@/shared/i18n/config";
import { usePathname, useRouter } from "next/navigation";
import { useTransition } from "react";

interface PillLanguageSwitcherProps {
  className?: string;
  size?: "sm" | "md";
}

export function PillLanguageSwitcher({
  className = "",
  size = "md",
}: PillLanguageSwitcherProps) {
  const router = useRouter();
  const pathname = usePathname();
  const [isPending, startTransition] = useTransition();
  const { locale, setLocale } = useLocaleStore();

  const handleLocaleChange = (code: Locale) => {
    if (locale === code) return;
    setLocale(code);

    const segments = pathname.split("/").filter(Boolean);
    if (segments.length > 0 && LOCALES.includes(segments[0] as Locale)) {
      segments[0] = code;
    } else {
      segments.unshift(code);
    }
    const newPath = `/${segments.join("/")}`;

    startTransition(() => {
      router.push(newPath);
    });
  };

  const isSmall = size === "sm";

  return (
    <div
      role="group"
      aria-label="Language selection"
      className={`inline-flex items-center rounded-full bg-white border border-gray-200/90 shadow-2xs ${
        isSmall ? "p-1" : "p-1"
      } ${isPending ? "opacity-70 cursor-wait" : ""} ${className}`}
    >
      <button
        type="button"
        onClick={() => handleLocaleChange("bn")}
        disabled={isPending && locale === "bn"}
        className={`rounded-full transition-all duration-200 cursor-pointer ${
          isSmall
            ? "px-2.5 py-1 text-xs font-semibold"
            : "px-3.5 py-1.5 text-body-sm font-semibold"
        } ${
          locale === "bn"
            ? "bg-primary text-white shadow-xs font-bold"
            : "text-gray-700 hover:text-gray-900"
        }`}
      >
        বাং
      </button>
      <button
        type="button"
        onClick={() => handleLocaleChange("en")}
        disabled={isPending && locale === "en"}
        className={`rounded-full transition-all duration-200 cursor-pointer ${
          isSmall
            ? "px-2.5 py-1 text-xs font-semibold"
            : "px-3.5 py-1.5 text-body-sm font-semibold"
        } ${
          locale === "en"
            ? "bg-primary text-white shadow-xs font-bold"
            : "text-gray-700 hover:text-gray-900"
        }`}
      >
        EN
      </button>
    </div>
  );
}
